<script setup lang="ts">import{useRouter}from'vue-router';import SummaryStrip from'../components/SummaryStrip.vue';import{useAnalysis}from'../composables/useAnalysis';const a=useAnalysis(),router=useRouter();function inspect(id:string){a.selectedId.value=id;router.push({name:'map'})}</script>
<template><template v-if="a.data.value"><SummaryStrip :data="a.data.value"/><section class="risk-section route-page"><header><h1>架构风险队列</h1><p>按影响范围和修复紧迫度排序；选择条目返回图谱定位模块。</p></header><div v-if="a.data.value.insights.length" class="risk-list"><button v-for="(item,index) in a.data.value.insights" :key="item.module" @click="inspect(item.module)"><span class="risk-index">{{String(index+1).padStart(2,'0')}}</span><span class="severity" :class="item.severity">{{item.severity}}</span><strong>{{item.title}}</strong><p>{{item.detail}}</p><code>{{item.module}}</code></button></div><div v-else class="empty-analysis"><strong>暂未发现高优先级架构风险</strong><p>可继续检查热点文件或接入包含更多模块的仓库。</p></div></section></template></template>
